  Fighter ChooseSwitch(SwitchRequest request){using(var dialog=new SwitchPromptForm(request))return dialog.ShowDialog(this)==DialogResult.OK?dialog.Selected:null;}
  void ApplySwitchRecords(TurnResult result){foreach(var change in result.Switches??new List<SwitchRecord>()){if(change==null||change.Incoming==null||change.Outgoing==null)continue;int incomingIndex=reserves[change.Side].FindIndex(x=>x.Data.name==change.Incoming.Data.name);if(incomingIndex>=0)reserves[change.Side].RemoveAt(incomingIndex);var outgoing=change.Outgoing.Copy();Bench(outgoing);if(!reserves[change.Side].Any(x=>x.Data.name==outgoing.Data.name))reserves[change.Side].Add(outgoing);}}
   public void RefreshView(){var encoreLog=new List<string>();foreach(var fighter in Fighters)Mechanics.RefreshEncore(db,fighter,encoreLog);if(encoreLog.Count>0)log=string.Join("\r\n",encoreLog)+"\r\n"+log;Mechanics.SetParties(Rules,Fighters,new IEnumerable<Fighter>[]{reserves[0],reserves[1]});UpdateHere();for(int i=0;i<2;i++){cards[i].ShowFighter(Fighters[i],Engine.Stats(Fighters[i],Fighters[1-i].Data.level,Rules)[0],i);moveCards[i].RefreshMoves(Fighters[i],db);directiveButtons[i].Text=DirectiveRules.Label(selections[i]);directiveButtons[i].Subtext=(trainers[i]==null?"트레이너 미적용":(trainers[i].name.Length>0?trainers[i].name:"이름 없는 트레이너"))+" · 대기 "+reserves[i].Count;directiveButtons[i].Enabled=Fighters[i].HP<=0||Fighters[i].Conditions.RampageTurns<=0;if(!directiveButtons[i].Enabled)directiveButtons[i].Subtext="「난동부리기」: 지정 불가";analyzeButtons[i].Enabled=!analyzed[i].Contains(Fighters[1-i].Data.name);analyzeButtons[i].Subtext=analyzeButtons[i].Enabled?"도감 사용":"해석 완료";cards[i].StateLine.Text=RuleBook.Summary(Fighters[i],Fighters[1-i],Rules);hints.SetToolTip(cards[i].StateLine,cards[i].StateLine.Text);hints.SetToolTip(directiveButtons[i],trainers[i]==null?"팀 편집에서 트레이너를 적용하면 4식·지령을 선택할 수 있습니다.":"4식과 지령은 선택 사항이며 각 항목은 1시합 1회입니다.");for(int j=0;j<Fighters[i].Moves.Length;j++){var m=db.moves.FirstOrDefault(v=>v.name==Fighters[i].Moves[j]);if(m==null)continue;string block=Mechanics.TargetsOpponent(m)?Mechanics.Block(db,Fighters[i],Fighters[1-i],m,Rules):"";var button=moveCards[i].Buttons[j];string unavailable=Mechanics.MoveBlock(Fighters[i],m);button.Enabled=unavailable.Length==0;button.Subtext=unavailable.Length>0?MoveCard.RestrictionLabel(unavailable):string.Join("/",m.types)+" / "+(block.Length>0?"무효":m.category=="변화"?(Mechanics.KnownMove(m)&&m.name!="날개쉬기"?"상태 적용":"수동 판정"):"상성 ×"+Mechanics.TypeEffect(db,Fighters[i],Fighters[1-i],m,Rules));hints.SetToolTip(button,(block.Length>0?block+"\n":"")+m.effect+"\n등록된 효과 외에는 수동 판정입니다.");button.Invalidate();}}fieldLabel.Text=RuleBook.Field(Rules,Fighters);fieldEffectBadge.Summary=FieldEffectRuntime.Summary(Rules.FieldEffects);hints.SetToolTip(fieldEffectBadge,FieldEffectRuntime.Detail(Rules.FieldEffects));turnLabel.Text="TURN  "+turn.ToString("00");calculate.Enabled=Fighters.All(f=>f.HP>0);back.Enabled=undo.Count>0;status.Text=Fighters.Any(f=>f.HP<=0)?"포켓몬이 쓰러졌습니다. 교대하거나 초기화하세요.":"기술을 선택하고 필요하면 4식·지령·선행입력을 선언한 뒤 배틀 !";battleState.SetReport(BattleStateReport.Build(db,Fighters,Rules,selections,trainers,trainerStates,reserves,here));if(resultForm!=null&&!resultForm.IsDisposed)resultForm.SetLog(log);}
  void UpdateHere(){for(int side=0;side<2;side++)if(!here[side]){int living=(Fighters[side].HP>0?1:0)+reserves[side].Count(x=>x.HP>0);if(RuntimeTriggers.HereNow(initialTeamSizes[side],living,Fighters[1-side])){here[side]=true;log=(side+1)+"팀 — 「여기다！」 성립\r\n"+log;}}}
  void Analyze(int side){var target=Fighters[1-side];if(analyzed[side].Contains(target.Data.name))return;Save();analyzed[side].Add(target.Data.name);var eventLog=new List<string>();RuntimeTriggers.Analyzed(Fighters[side],reserves[side].Concat(new[]{Fighters[side]}),target,eventLog.Add);log=(side+1)+"팀이 도감으로 "+target.Data.name+"의 데이터를 해석했다.\r\n"+string.Join("\r\n",eventLog)+"\r\n\r\n"+log;using(var form=new AnalysisForm(target))form.ShowDialog(this);RefreshView();}
  bool ConfirmOptionalEffect(Fighter source,Fighter target,Potential potential){if(source==null||target==null||potential==null)return false;int side=Array.FindIndex(Fighters,x=>x!=null&&x.Data!=null&&x.Data.name==source.Data.name);if(side<0||analyzed[side].Contains(target.Data.name))return false;if(GameDialog.Show(this,"『"+potential.name+"』으로 "+target.Data.name+"의 데이터를 해석할까요?","선택 발동",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return false;analyzed[side].Add(target.Data.name);using(var form=new AnalysisForm(target))form.ShowDialog(this);return true;}
  void ShowResults(){if(resultForm==null||resultForm.IsDisposed)resultForm=new ResultForm();resultForm.SetLog(log);if(!resultForm.Visible)resultForm.Show(this);resultForm.Activate();}
  void ShowTeamEditor(){if(dataEditorForm==null||dataEditorForm.IsDisposed){dataEditorForm=new DataEditorForm(LoadFromEditor,LoadTrainerFromEditor);dataEditorForm.FormClosed+=(s,e)=>dataEditorForm=null;dataEditorForm.Show(this);}else dataEditorForm.Activate();}
  void LoadFromEditor(PokemonRecord source,int side){string warning;var data=EditorBridge.ToPokemon(source,db,out warning,trainers[side],trainerStates[side]);Save();var fighter=new Fighter(data);fighter.AA=source.asciiArt;TrainerAccessRules.ApplyTrainerPassives(fighter,trainers[side],trainerStates[side]);if(Fighters[side].Data.name!=data.name){reserves[side].RemoveAll(x=>x.Data.name==data.name);reserves[side].Add(Fighters[side].Copy());}Fighters[side]=fighter;selections[side]=new TurnSelection();log="팀 편집기에서 "+data.name+"을 "+(side==0?"왼쪽":"오른쪽")+" 배틀 슬롯에 불러왔습니다."+(warning.Length>0?"\r\n"+warning:"")+"\r\n\r\n"+log;RefreshView();status.Text=data.name+" → "+(side==0?"왼쪽":"오른쪽")+" 슬롯 적용 완료 · 이전 포켓몬은 대기"+(warning.Length>0?" (일부 항목 제외)":"");}
  void LoadTrainerFromEditor(TrainerRecord source,int side){Save();string json=new JavaScriptSerializer().Serialize(source);trainers[side]=new JavaScriptSerializer().Deserialize<TrainerRecord>(json);trainerStates[side]=new TrainerBattleState{Trainer=trainers[side]};selections[side]=new TurnSelection();log=(source.name.Length>0?source.name:"이름 없는 트레이너")+"를 TRAINER "+(side+1)+"에 적용했습니다. 지령 사용 이력이 초기화됩니다.\r\n\r\n"+log;RefreshView();}
  public void Smoke(){var old=Fighters[0].HP;var savedRules=Rules.Copy();Rules.Weather="비";Rules.WeatherTurns=3;Rules.Sides[0].Reflect=3;Battle();if(turn!=2||log.Length==0)throw new Exception("Turn UI failed");Undo();if(turn!=1||Fighters[0].HP!=old||Rules.WeatherTurns!=3||Rules.Sides[0].Reflect!=3)throw new Exception("Undo UI failed");Rules=savedRules;Rules.Sides[0].Reflect=0;Rules.Sides[0].StealthRock=true;Rules.Sides[1].Spikes=2;Rules.Sides[1].ToxicSpikes=1;RefreshView();if(resultForm!=null)resultForm.Close();using(var f=new FighterForm(db,Fighters[0],Fighters[1].Data.level,Rules)){f.CreateControl();}using(var f=new RulesForm(Rules)){f.CreateControl();}}
 }
 class LogView:Panel {
