 static class Program {
  static void Capture(Form form,string path){Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
   [STAThread]static int Main(string[] args){try{var db=Database.Load();if(args.Length>0&&args[0]=="--self-test"){File.WriteAllText(args.Length>1?args[1]:"self-test.txt",Engine.Test(db)+"\r\n"+MechanicsTests.Run(db));return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Fonts.Load();Theme.Instant=args.Length>0;if(args.Length>1&&args[0]=="--flow-preview"){FlowPreview.Run(db,args[1]);return 0;}if(args.Length==0){Application.Run(new StartForm(db));return 0;}var form=new MainForm(db);if(args.Length>1&&args[0]=="--render-preview"){form.TestMode=true;form.Shown+=(s,e)=>{form.Smoke();Capture(form,args[1]);var savedFighters=form.Fighters.Select(f=>f.Copy()).ToArray();var savedRules=form.Rules.Copy();form.Rules.Weather="비";form.Rules.WeatherTurns=3;form.Rules.Terrain="일렉트릭필드";form.Rules.TerrainTurns=4;form.Fighters[0].Status="마비";form.Rules.Sides[1].Reflect=3;form.RefreshView();Capture(form,args[1]+".active.png");form.Fighters=savedFighters;form.Rules=savedRules;form.RefreshView();using(var conditions=new ConditionsForm(db,form.Fighters[0],form.Fighters[1],form.Rules)){conditions.Show();Capture(conditions,args[1]+".conditions.png");conditions.Close();}using(var guide=new GuideForm(db)){guide.Show();Capture(guide,args[1]+".guide.png");guide.Close();}using(var editor=new FighterForm(db,form.Fighters[0],form.Fighters[1].Data.level,form.Rules)){editor.Show();Capture(editor,args[1]+".editor.png");editor.Close();}using(var settings=new RulesForm(form.Rules)){settings.Show();Capture(settings,args[1]+".settings.png");settings.Close();}using(var result=new ResultForm()){result.SetLog("TURN 01\r\n선데이의 파괴광선!\r\n잭 한마에게 297 대미지.");result.Show();Capture(result,args[1]+".log.png");result.Close();}form.Close();};}Application.Run(form);return 0;}catch(Exception ex){if(args.Length>0){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"error.txt"),ex.ToString());return 1;}GameDialog.Show(ex.Message,"AA BATTLE 오류",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 }
